UPDATE CKClone SET "ID"=NULL,"Type"='CIVILIZATION_CK_KINGDOM',"Description"='TXT_KEY_CK_CIV',"ShortDescription"='TXT_KEY_CK_SHORT',"Adjective"='TXT_KEY_CK_ADJECTIVE',"Civilopedia"='TXT_KEY_CK_CIV_PEDIA',"CivilopediaTag"='TXT_KEY_CK_CIV5',"Strategy"='TXT_KEY_CK_STRATEGY',"DefaultPlayerColor"='PLAYERCOLOR_CK',"Playable"=1,"AIPlayable"=0,"PackageID"=NULL,"DawnOfManQuote"='TXT_KEY_CK_DAWN',"DawnOfManAudio"='',"DawnOfManImage"='CKDawn.dds',"MapImage"='CKMap.dds',"PortraitIndex"=0,"IconAtlas"='CK_CIV_ATLAS',"AlphaIconAtlas"='CK_ALPHA_ATLAS';
